# _curl — 一律绕开本机代理。这台机器上常年挂着 127.0.0.1:7897,走代理时
# --resolve 会被它接管,验证结果就不是真的了。所有对外探测都走这个包装。
_curl() { curl --noproxy '*' "$@"; }

# dns_hijacked — 本机 DNS 是不是被劫持了。判据:随便编一个不该存在的名字,
# 如果也能"解析"出地址,说明有东西在伪造应答(代理的 fake-ip 模式就是这样,
# 它给每个域名发一个 198.18.0.x 的假地址)。这种情况下本机查解析毫无意义。
dns_hijacked() {
  local canary="wizard-canary-$$-nonexistent.col.com"
  [[ -n "$(dig +short "$canary" A 2>/dev/null | head -1)" ]]
}

# probe_tls HOST IP — 不依赖 DNS,直接把域名钉到指定地址上做一次严格 TLS 校验。
# 回显 HTTP 状态码;握手或证书校验没过时回显 000。
probe_tls() {
  _curl -sS -m 12 --resolve "${1}:443:${2}" \
    -o /dev/null -w '%{http_code}' "https://${1}${HEALTH_PATH}" 2>/dev/null || printf '000'
}

# connected_ip — 按真实解析访问,回显实际连上的地址。这是"解析生效了没"最靠谱的
# 信号:比 dig 强,因为它证明的是连接真的落到了那台机器上。
connected_ip() {
  _curl -sS -m 12 -o /dev/null -w '%{remote_ip}' \
    "https://${PROD_HOST}${HEALTH_PATH}" 2>/dev/null || printf ''
}

banner "生产环境上 TLS · ${PROD_HOST}"

