# ── 2 ─────────────────────────────────────────────────────────────────────
stage "免 DNS 预验证"
say "在惊动震宇之前,先自己证明这条路走得通。"
say "把域名临时钉到 ${PROD_IP} 上打一次,证书链和域名匹配都做严格校验。"
say ""
say "  正在探测 https://${PROD_HOST}${HEALTH_PATH} ..."
PRECHECK_CODE="$(probe_tls "$PROD_HOST" "$PROD_IP")"
if [[ "$PRECHECK_CODE" == "200" ]]; then
  printf '  %s✓%s 通了(%s)。证书认 %s,负载均衡也把它路由到了生产服务。\n' \
