  say "这一步不过,后面派工单就是白派——建议先停下来查清楚。"
  write_env TLS_PRECHECK "fail-${PRECHECK_CODE}"
  SKIPPED+=("免 DNS 预验证没过(${PRECHECK_CODE})—— 方案可行性存疑,先查清楚")
  confirm "还要继续吗?" || { finish; exit 0; }
fi
pause

