  step "把它的转发动作改成重定向到 HTTPS:443,状态码用 301。"
  note "各家控制台这块的措辞不一样(可能叫「重定向」也可能在转发规则里配),"
  note "以你屏幕上看到的为准。做没做成不看措辞,看下面的回验。"
  pause "改完回车,这里帮你验一次。"
  say ""
  REDIR_CODE="$(_curl -sS -m 12 -o /dev/null -w '%{http_code}' \
    "http://${PROD_HOST}${HEALTH_PATH}" 2>/dev/null || printf '000')"
  REDIR_LOC="$(_curl -sS -m 12 -o /dev/null -w '%{redirect_url}' \
    "http://${PROD_HOST}${HEALTH_PATH}" 2>/dev/null || printf '')"
  if [[ "$REDIR_CODE" =~ ^30[128]$ && "$REDIR_LOC" == https://* ]]; then
    printf '  %s✓%s 80 返回 %s,跳到 %s\n' "$GREEN" "$RESET" "$REDIR_CODE" "$REDIR_LOC"
    write_env HTTP_REDIRECT "ok-${REDIR_CODE}"
  else
    warn "回验没看到跳转(状态码 ${REDIR_CODE},跳转目标「${REDIR_LOC:-空}」)。"
    say "明文入口还开着。控制台的改动可能没保存,或者还没生效。"
    SKIPPED+=("80 到 443 的强制跳转(回验返回 ${REDIR_CODE})")
  fi
else
  SKIPPED+=("80 到 443 的强制跳转 —— 没做的话明文入口依然开着")
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "收尾"
say "人能做的部分到此为止。剩下的是改代码,交回给 agent:"
say ""
step "docs/contracts/environment-governance.md:prod 那行入口改成 https://${PROD_HOST}。"
step "命令行工具仓 docs/adr/0001-trusted-endpoint-catalogue.md:删掉 HTTP 标注与"
note "    每次连接打的那行 stderr 警告(该 ADR 说的条件到这里就齐了)。"
step "deploy/k8s/overlays/prod:把 80 跳 443 落进清单。控制台改了但仓库没有,"
note "    下次 apply 会把它冲掉。仓库里现在只有 80 和 443 两个 ingress,没有重定向。"
say ""
note "不用改的两处(查过了):alb-instance-patch.yaml 的实例 ID 和证书 ID 早在 #289"
note "填好了;config/env.production.json 没有记录本站入口地址的键。"
say ""
note "这几处已经开成单子了,细节和验收都在里面:"
note "  https://github.com/col-shortdrama/zhongwen-shortdrama-main/issues/318"
note "上面这些值都在 ${ENV_FILE} 里,直接读给 agent 就行。"
pause

finish
